6// A class to create and add nodes
7template <typename T>
8class TreeNode {
9public:
10
11    // Constructor prints each time a node is created
12    TreeNode(T val): data(val) {
13        cout << "Node " << data << " was created\n";
14    }
15
16    void add_child(vector<TreeNode<T>*> child_arr) {
17        children = child_arr;
18        cout << "Nodes ";
19
20        // Print a message that lists the children that were added
21        for(const auto& item: children) {
22            cout << item->data << " ";
23        }
24        cout << "were added as children to Node " << data << "\n";
25    }
26
27    T data;
28    vector<TreeNode<T>*> children;
29};
