31// A class to create tree and perform tree operations
32template <typename T>
33class Tree {
34public:
35
36    Tree(TreeNode<T>* root_node): root(root_node) {
37        cout << "A tree was created\n";
38    };
39
40    TreeNode<T>* root {nullptr};
41};
42
43int main() {
44
45    // Create the root node
46    TreeNode<string>* root = new TreeNode<string>("Book");
47
48    // Create children of root
49    TreeNode<string>* child1 = new TreeNode<string>("1");
50    TreeNode<string>* child2 = new TreeNode<string>("2");
51    TreeNode<string>* child3 = new TreeNode<string>("3");
52
53    // Create leaf nodes
54    TreeNode<string>* child1_1 = new TreeNode<string>("1.1");
55    TreeNode<string>* child1_2 = new TreeNode<string>("1.2");
56    TreeNode<string>* child1_3 = new TreeNode<string>("1.3");
57    TreeNode<string>* child1_4 = new TreeNode<string>("1.4");
58    TreeNode<string>* child2_1 = new TreeNode<string>("2.1");
59    TreeNode<string>* child3_1 = new TreeNode<string>("3.1");
60    TreeNode<string>* child3_2 = new TreeNode<string>("3.2");
61    TreeNode<string>* child3_3 = new TreeNode<string>("3.3");
62
63    // Describe relationships between the nodes
64    // and add children to the root node
65    root->add_child({child1, child2, child3});
66
67    // Add children to child1
68    child1->add_child({child1_1, child1_2, child1_3, child1_4});
69
70    // Add children to child2
71    child2->add_child({child2_1});
72
73    // Add children to child3
74    child3->add_child({child3_1, child3_2, child3_3});
75
76    // Create the tree
77    Tree<string> general_tree = Tree<string>(root);
78
79    return 0;
80}
